<?php
declare(strict_types=1);
namespace App\Interface\Http\Catalog\Controller;
use App\Application\Catalog\DTO\Request\CreateExamWithNoticeRequestDto;use App\Application\Catalog\Service\CreateExamWithNoticeService;use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use DomainException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class ExamNoticeController { public function __construct(private readonly AuthService $auth,private readonly CreateExamWithNoticeService $create,private readonly ApiResponseFactory $responses) {} public function create(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,CreateExamWithNoticeRequestDto $input):ResponseInterface { try{$user=$this->auth->currentUser($access);if(!in_array('ADMIN',$user->roles,true))throw new \LogicException();return $this->responses->success($response,$this->create->create($input),(string)$request->getAttribute('request_id'),201);}catch(\InvalidArgumentException){return $this->responses->problem($response,'VALIDATION_FAILED','Um ou mais campos sao invalidos.',422,(string)$request->getAttribute('request_id'));}catch(DomainException|UnavailableUserException|\LogicException){return $this->responses->problem($response,'FORBIDDEN','Permissao insuficiente.',403,(string)$request->getAttribute('request_id'));} } }
